package bottlesong

import (
	"fmt"
	"strings"
)

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for i := startBottles; i > startBottles-takeDown; i-- {
		if i != startBottles {
			lines = append(lines, "")
		}
		lines = append(lines,
			fmt.Sprintf("%s green bottles hanging on the wall,", Title(verseNumber(i))),
			fmt.Sprintf("%s green bottles hanging on the wall,", Title(verseNumber(i))),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s hanging on the wall.", verseNumber(i-1)),
		)
	}
	return lines
}

// verseNumber returns the count phrase for n bottles, lowercase.
func verseNumber(n int) string {
	if n == 0 {
		return "no green bottles"
	}
	return fmt.Sprintf("%s green bottle%s", Title(numberWord(n)), plural(n))
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

func numberWord(n int) string {
	switch n {
	case 1:
		return "one"
	case 2:
		return "two"
	case 3:
		return "three"
	case 4:
		return "four"
	case 5:
		return "five"
	case 6:
		return "six"
	case 7:
		return "seven"
	case 8:
		return "eight"
	case 9:
		return "nine"
	case 10:
		return "ten"
	default:
		return strings.ToLower(fmt.Sprintf("%d", n))
	}
}

// Title capitalizes the first rune of s.
func Title(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

